facilityFormItem.valueChangedEventHandler:
     
      functions.removeError(context.vacationIdError);
      if (functions.getValues().IsVacationIdChangedFirstTime == true)
      {
        if (functions.getValues().VacationId) {
          var vacationId = ESS.parseFloat(functions.getValues().VacationId);
          var vacationId2 = ESS.parseFloat(functions.getValues().VacationId2);
          var vacationId3 = ESS.parseFloat(functions.getValues().VacationId3);

          context.setDataSource(vacationId, ["VacationId2", "VacationId3"]);

          var vacationArray = [vacationId, vacationId2, vacationId3];
          var vacArrStr = JSON.stringify(vacationArray);
          functions.setValue('VacationIds', vacArrStr);
          if (vacationId2 && vacationId === vacationId2 || vacationId3 && vacationId === vacationId3) {
            context.vacationIdError = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_REWORKSHIFTVACATION_ERRVACATIONKINDID'), undefined, ESS.enums.FormErrorType.FORM_REQUIRED, 'VacationId');
          }
        }
      } else {
        functions.setValue('IsVacationIdChangedFirstTime', true);
      }

      if (functions.getValues().IsVacationId2ChangedFirstTime == true)
      {
        functions.removeError(context.vacationId2Error);
        var vacationId = ESS.parseFloat(functions.getValues().VacationId);
        var vacationId2 = ESS.parseFloat(functions.getValues().VacationId2);
        var vacationId3 = ESS.parseFloat(functions.getValues().VacationId3);
        var vacationArray = [vacationId, vacationId2, vacationId3];
        var vacArrStr = JSON.stringify(vacationArray);
        functions.setValue('VacationIds', vacArrStr);
        
        context.setDataSource(vacationId, ["VacationId3"]);

        if (vacationId2) {
          if (vacationId && vacationId2 === vacationId || vacationId3 && vacationId2 === vacationId3) {
            context.vacationId2Error = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_REWORKSHIFTVACATION_ERRVACATIONKINDID'), undefined, ESS.enums.FormErrorType.FORM_REQUIRED, 'VacationId2', undefined);
          }
        } else {
          functions.setValue('VacationId3', null);
        }

        var rows = functions.getValues().NewVacationDateGrid;
        var vacationIds = functions.getValues().VacationIds;
        var vacationKindIdsArray = [];
        var vacationDurationArray = [];
        rows.forEach(row => {
          if (row.rowValues.VacationKindId && row.rowValues.BeginDate && row.rowValues.VacationDuration) {
