          functions.removeError(context.errorDurations);
          if(durationErrors.length > 0) {
            context.errorDurations = functions.showError(durationErrors);
          }
        });
        var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${formItem.value}]`;
