          functions.removeError(context.vacationId2Error);
          if(changingError.length > 0) {
            context.vacationId2Error = functions.showError(changingError);
          }
        });
        functions.setIsItemHidden('VacationId3', !formItem.value);
      }
      else
      {
        functions.setValue('IsVacationId2ChangedFirstTime', true);
      }

      if (functions.getValues().IsVacationId3ChangedFirstTime == true)
      {
        functions.removeError(context.vacationId3Error);
