        var vacationId2 = ESS.parseFloat(functions.getValues().VacationId2);
        var vacationId3 = ESS.parseFloat(functions.getValues().VacationId3);
        var vacationArray = [vacationId, vacationId2, vacationId3];
        var vacArrStr = JSON.stringify(vacationArray);
        functions.setValue('VacationIds', vacArrStr);
        
        if (functions.getValues().VacationId3) {
          if (vacationId && vacationId3 === vacationId || vacationId2 && vacationId3 === vacationId2) {
            context.vacationId3Error = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_REWORKSHIFTVACATION_ERRVACATIONKINDID'), undefined, ESS.enums.FormErrorType.FORM_REQUIRED, 'VacationId3', undefined);
          }
        }

        var rows = functions.getValues().NewVacationDateGrid;
        var vacationIds = functions.getValues().VacationIds;
        var vacationKindIdsArray = [];
        var vacationDurationArray = [];
        rows.forEach(row => {
          if (row.rowValues.VacationKindId && row.rowValues.BeginDate && row.rowValues.VacationDuration) {
              vacationKindIdsArray.push(row.rowValues.VacationKindId);
              vacationDurationArray.push(row.rowValues.VacationDuration);
          };
        });

        var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
        ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
          functions.removeError(context.errorDurations);
          if(durationErrors.length > 0) {
            context.errorDurations = functions.showError(durationErrors);
          }
        });
        var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${formItem.value}]`;
        ESS.network.sendRequest(urlTemplate).then(function (changingError){
          functions.removeError(context.vacationId3Error);
          if(changingError.length > 0) {
            context.vacationId3Error = functions.showError(changingError);
          }
        });
      }
      else
      {
        functions.setValue('IsVacationId3ChangedFirstTime', true);
      }

var vacationIds = functions.getValues().VacationIds;
ESS.network.sendRequest(`/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`)
.then(function (vacationKindsInfo) {
  var vacationKindArray = [];
  vacationKindsInfo.forEach(function (vacationKindInfo) {
    vacationKindArray.push(vacationKindInfo.id);
  });
  var rows = functions.getValues().NewVacationDateGrid;
  rows.forEach(row => {
    if (row.rowValues.VacationKindId && !vacationKindArray.includes(Number(row.rowValues.VacationKindId))) {
      functions.removeItem('NewVacationDateGrid', row.rowIndex);
    }
  });
});

functions.setDataSource({
  parameterName: 'VacationKindId', 
  newDataSource: `/api/functions/GetVacationKindsInfo?vacationIds=${vacationIds}`,
  shouldSaveValue: true
});

if (context.isJustOpened){
  var rows = functions.getValues().NewVacationDateGrid;
  for (var i = 0; i < context.newVacationData.length; i++) {
    var rowIndex = rows.length > i ? rows[i].rowIndex : functions.addItem('NewVacationDateGrid');
    functions.setValue('NewVacationDateGrid', context.newVacationData[i].VacationKindId, rowIndex, 'VacationKindId')
    functions.setValue('NewVacationDateGrid', context.newVacationData[i].Begin, rowIndex, 'BeginDate');
    functions.setValue('NewVacationDateGrid', context.newVacationData[i].Duration, rowIndex, 'VacationDuration');
    functions.setValue('NewVacationDateGrid', context.newVacationData[i].End, rowIndex, 'EndDate');
  }
  delete(context.isJustOpened);
  delete(context.newVacationData);
}

facilityFormItem.itemRemovedEventHandler:
var rows = functions.getValues().NewVacationDateGrid;
var VacationsData = '';
rows.forEach(row => {
  VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.VacationDuration + '~' + row.rowValues.EndDate +'!';
});
functions.setValue('VacationsData', VacationsData);

column.valueChangedEventHandler:
            var initiatorId = functions.getValues().InitiatorId;
            var vacationKindId = formItem.value;
            var beginDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['BeginDate'];
            var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationDuration'];
            var endDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['EndDate'];
            
            if (vacationKindId != null && durationValue != null && beginDateValue != null) {
              var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
              ESS.network.sendRequest(url)
              .then(function (newEndDateValue) {
                if (new Date(newEndDateValue).getTime() != new Date(endDateValue).getTime()) {
                  functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
                }
              });
            }

            var rows = functions.getValues().NewVacationDateGrid;
            var vacationIds = functions.getValues().VacationIds;
            var vacationKindIdsArray = [];
            var vacationDurationArray = [];
            rows.forEach(row => {
              if (row.rowValues.VacationKindId != null && row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                  vacationKindIdsArray.push(row.rowValues.VacationKindId);
                  vacationDurationArray.push(row.rowValues.VacationDuration);
              };
            });
            var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
            ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
              functions.removeError(context.errorDurations);
              if(durationErrors.length > 0) {
                context.errorDurations = functions.showError(durationErrors);
              }
            });

            var today = new Date();
            var yesterday = new Date(today);
            yesterday.setDate(today.getDate() -1);
            var beginDateValue = formItem.value;
            var dateFromControl = new Date(beginDateValue).getTime();
            functions.removeError(context.errorDate);
            if (dateFromControl < yesterday.getTime()) {
              context.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
            }
            var initiatorId = functions.getValues().InitiatorId;
            var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationDuration'];
            var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationKindId'];

            if (durationValue != null && beginDateValue != null && vacationKindId != null) {
              var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
              context.sendRequest(url)
              .then(function (newEndDateValue) {
                functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
              });
            };

            var initiatorId = functions.getValues().InitiatorId;
            var beginDateValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['BeginDate'];
            var durationValue = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationDuration'];
            var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationKindId'];
            
            if (durationValue <= 0) {
              functions.removeError(context.errorId);
              context.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
            } else {
              functions.removeError(context.errorId);
            }

            if (durationValue != null && beginDateValue != null && vacationKindId != null) {
              var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['EndDate'];
              var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationKindId=${vacationKindId}`;
              context.sendRequest(url)
              .then(function (newEndDateValue) {
                if (new Date(newEndDateValue).getTime() != new Date(endDate).getTime()) {
                  functions.setValue('NewVacationDateGrid', newEndDateValue, formItem.index, 'EndDate');
                }
              });
            };

            var initiatorId = functions.getValues().InitiatorId;
            var beginDate = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['BeginDate'];
            var endDate = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['EndDate'];
            var vacationKindId = functions.getValues().NewVacationDateGrid.find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationKindId'];
            functions.removeError(context.errorEndDate);

            if (beginDate != null && endDate != null && vacationKindId != null) 
            {
              var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
              context.sendRequest(url)
              .then(function (newDuration) {
                if (newDuration <= 0) {
                  context.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
                }
                else {
                  var rows = functions.getValues().NewVacationDateGrid;
                  var vacationKindIdsArray = [];
                  var beginDateArray = [];
                  var vacationDurationArray = [];
                  var endDateArray = [];
                  var VacationsData = '';
                  rows.forEach(row => {
                    if (row.rowValues.VacationKindId != null && row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                      vacationKindIdsArray.push(row.rowValues.VacationKindId);
                      var beginDate = `"${row.rowValues.BeginDate}"`;
                      beginDateArray.push(beginDate);
                      vacationDurationArray.push(row.rowValues.VacationDuration);
                      var endDate = `"${row.rowValues.EndDate}"`;
                      endDateArray.push(endDate);
                      VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
                    };
                  });
                  functions.setValue('VacationsData', VacationsData);
                  var vacationIds = functions.getValues().VacationIds;

                  var url = `/api/functions/CheckVacationRequiredDuration?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                  context.sendRequest(url)
                  .then(function (errors) {
                    if (errors.length > 0){
                      functions.removeError(context.errorRequiredDuration);
                      context.errorRequiredDuration = functions.showError(errors);
                    }
                    else{
                      functions.removeError(context.errorRequiredDuration);
                    }
                  });

                  var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                  context.sendRequest(urlTemplate).then(function (errors){
                    if(errors.length > 0) {
                      functions.removeError(context.errorVacations);
                      context.errorVacations = functions.showError(errors);
                    } else {
                      functions.removeError(context.errorVacations);
                    }
                  });
                  if (vacationKindIdsArray.length > 0) {
                    var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
                    context.sendRequest(urlTemplate).then(function (durationErrors){
                      if(durationErrors.length > 0) {
                        functions.removeError(context.errorDurations);
                        context.errorDurations = functions.showError(durationErrors);
                      } else {
                        functions.removeError(context.errorDurations);
                      }
                    });
                  }
                  var assignmentId = functions.getValues().AssignmentId;
                  var urlTemplate = `/api/functions/CheckExecutionShiftVacationsInRework?vacationIds=${vacationIds}&assignmentId=${assignmentId}`;
                  context.sendRequest(urlTemplate).then(function (errors){
                    if(errors.length > 0) {
                      functions.removeError(context.errorExecutionShift);
                      context.errorExecutionShift = functions.showError(errors);
                    } else {
                      functions.removeError(context.errorExecutionShift);
                    }
                  });
                }
              });
            }
                        
            var url = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
            context.sendRequest(url)
            .then(function (warning) {
              if(warning.length > 0)
                ESS.toasts.showToast(warning, ESS.enums.ToastType.WARNING, true);
            });

facilityFormItem.onClickEventHandler:
        const id = 'reworkChangeVacationPlanningTool';
        let intervalId;
        const callDialog = () => {
          if (!Object.keys(context.canShowDialog).length) {
            const timeline = {
              type: ESS.enums.DialogItemType.TEXT,
              name: 'timeline',
              properties: {
                text: `
                  <component
                    name="VacationPlanningTool"
                    public-name="Directum_VacationPlanningTool_1_0"
                    module-name="loaders"
                    loader-name="lk-loader"
                    dialog-id="${id}"
                  />
                `,
              },
            };

            const newVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'Vacations',
                properties: {
                  initialValue: JSON.stringify(functions.getValues().NewVacationDateGrid),
                  isHidden: true,
                },
            }

            const oldVacations = {
              type: ESS.enums.DialogItemType.INPUT,
                name: 'OldVacations',
                properties: {
                  initialValue: functions.getValues().VacationIds,
                  isHidden: true,
                },
            }

            const performerId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'PerformerId',
              properties: {
                initialValue: functions.getValues().InitiatorId,
                isHidden: true,
              },
            };

            const entityGuid = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'EntityGuid',
              properties: {
                initialValue: 'd54a4fd2-a4cc-4e00-aa31-e4f692b334a6',
                isHidden: true,
              },
            };

            const assignmentId = {
              type: ESS.enums.DialogItemType.INPUT,
              name: 'AssignmentId',
              properties: {
                initialValue: functions.getValues().AssignmentId,
                isHidden: true,
              },
            };

            const items = [
              timeline,
              performerId,
              newVacations,
              oldVacations,
              entityGuid,
              assignmentId,
            ];

            ESS.dialogs.createDialog({
              id,
              properties: {
                width: ESS.enums.DialogWidth.WIDE,
                isFullScreen: true,
              },
              title: ESS.L('@HRPROVACATIONS.FACILITIES_SCHEDULEVACATION_DIALOG_TITLE'),
              items,
            });
            clearInterval(intervalId);
          }
        }

        intervalId = setInterval(callDialog, 300);

facility.openingEventHandler:
    context.canShowDialog = {};
    context.sendRequest = (...args) => {
      const key = Date.now();
      context.canShowDialog[key] = '';
      return ESS.network.sendRequest(...args).finally(() => delete context.canShowDialog[key]);
    };
    context.setDataSource = (vacationId, formItems, isFirstTime = false) => {
      var count = 0;
      ESS.network.sendRequest(`/api/functions/GetCurrentChangeVacations?assignmentId=${functions.getValues().AssignmentId}`)
      .then(function (OldShiftVacation) {
        var oldVacations = [OldShiftVacation.FirstVacationId, OldShiftVacation.SecondVacationId, OldShiftVacation.ThirdVacationId];
        var initiatorId = OldShiftVacation.InitiatorId;
        var confirmationAssignmentId = OldShiftVacation.ConfirmationAssignmentId;
        ESS.network.sendRequest(`/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${vacationId}&isForReworkCardOpen=true`)
        .then(function (response) {
          var vacationsFromConfirmations = response.map((x) => {return x.id});
          formItems.forEach(item => {
              if (isFirstTime && oldVacations[count] != 0){
                if (vacationsFromConfirmations.includes(oldVacations[count]))
                  functions.setDataSource(item, `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${confirmationAssignmentId}&vacationId=${vacationId}&isForReworkCardOpen=true`, oldVacations[count]);
                else
                  functions.setDataSource(item, `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${null}&vacationId=${vacationId}&isForReworkCardOpen=false`, oldVacations[count]);
              }
              else
                functions.setDataSource(item, `/api/functions/GetCurrentEmployeeVacationsForShift?employeeId=${initiatorId}&confirmationAssignmentId=${null}&vacationId=${vacationId}&isForReworkCardOpen=false`);
            count++;
          });    
        });
      });  
    }

    ESS.network.sendRequest(`/api/functions/GetCurrentChangeVacations?assignmentId=${functions.getValues().AssignmentId}`)
    .then(function (OldShiftVacation) {
      var vacationId = OldShiftVacation.FirstVacationId;
      var vacationId2 = OldShiftVacation.SecondVacationId;
      var vacationId3 = OldShiftVacation.ThirdVacationId;
      var initiatorId = OldShiftVacation.InitiatorId;
 
      functions.setValue('Reason', OldShiftVacation.Reason);
      context.setDataSource(vacationId, ["VacationId", "VacationId2", "VacationId3"], true);
      context.newVacationData = OldShiftVacation.NewVacationData;
      context.isJustOpened = true;

      functions.setValue('InitiatorId', initiatorId);
      ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=true`)
      .then(function (VacationStatementData) 
      {
        var templateId = VacationStatementData.TemplateId;
        var docKindId = VacationStatementData.DocumentKindId;
        functions.setValue('TemplateId', templateId);
        functions.setValue('DocumentKindId', docKindId);
        functions.setValue('IsFromEssAccount', true);
         
        ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
        .then(function (emps) {
          if (emps.positions.length > 1){
            functions.setValue('Department', OldShiftVacation.Department);
            functions.setValue('BusinessUnit', OldShiftVacation.Organization);
            functions.setValue('JobTitle', OldShiftVacation.JobTitle);
          }
          
          ESS.network.sendRequest(`/api/functions/GetShiftVacationStatementId?assignmentId=${functions.getValues().AssignmentId}`)
          .then(function (statementId){
            functions.setValue('StatementId', statementId);
          })
          resolve();
        })
      })
    })
    .catch(function (error) {
      ESS.toasts.showToast(error.message,  ESS.enums.ToastType.ERROR, false);
      reject();
    });

facility.openedEventHandler:
    ESS.network.sendRequest(`/api/functions/GetCurrentChangeVacations?assignmentId=${functions.getValues().AssignmentId}`)
    .then(function (OldShiftVacation) {
      var vacationId = OldShiftVacation.FirstVacationId;
      var vacationId2 = OldShiftVacation.SecondVacationId;
      var vacationId3 = OldShiftVacation.ThirdVacationId;
      var confirmationAssignmentId = OldShiftVacation.ConfirmationAssignmentId;

      functions.setIsItemDisabled('VacationId', confirmationAssignmentId != null);
      if (vacationId2)
      {
        functions.setIsItemHidden('VacationId3', false);
        functions.setIsItemDisabled('VacationId2', confirmationAssignmentId != null);
      }
      else
      {
        functions.setValue('IsVacationId2ChangedFirstTime', true);
      }
      if (vacationId3) 
      {
        functions.setIsItemDisabled('VacationId3', confirmationAssignmentId != null);
      }
      else
      {
        functions.setValue('IsVacationId3ChangedFirstTime', true);
      }

      var vacationArray = [vacationId, vacationId2, vacationId3];
      var vacArrStr = JSON.stringify(vacationArray);
      functions.setValue('VacationIds', vacArrStr);
    });
